/* OpenLearnHub — Global Styles */

:root {
  --navy: #0a0a23;
  --gold: #FEAC32;
  --link-blue: #002EAD;
  --bg: #ffffff;
  --bg-light: #f5f6f7;
  --text: #1b1b32;
  --text-muted: #5a5a7a;
  --border: #e0e0e8;
  --tag-ai: #c1e1ff;
  --tag-ai-text: #003366;
  --tag-scraping: #d4f0c1;
  --tag-scraping-text: #1a4a00;
  --tag-db: #ffe0b2;
  --tag-db-text: #6b2f00;
  --tag-elastic: #e8d5f5;
  --tag-elastic-text: #4a0080;
  --tag-data: #ffecd2;
  --tag-data-text: #7a3000;
  --tag-default: #e8e8f0;
  --tag-default-text: #444466;
  --radius: 8px;
  --radius-lg: 12px;
  --shadow: 0 2px 8px rgba(0,0,0,0.08);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.12);
  --shadow-hover: 0 8px 24px rgba(0,0,0,0.15);
  --font: 'Inter', system-ui, -apple-system, sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  font-size: 16px;
}

a { color: inherit; text-decoration: none; }
a:hover { color: var(--link-blue); }

img { max-width: 100%; display: block; }

button { cursor: pointer; font-family: var(--font); }

/* ─── Header ─── */
.site-header {
  background: var(--navy);
  color: white;
  padding: 0 24px;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 2px 8px rgba(0,0,0,0.3);
}

.header-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: 16px;
  height: 64px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  font-size: 1.1rem;
  color: white;
  white-space: nowrap;
  flex-shrink: 0;
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--gold);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 900;
  font-size: 1.1rem;
  color: var(--navy);
}

.header-search {
  flex: 1;
  max-width: 480px;
}

.header-search input {
  width: 100%;
  background: rgba(255,255,255,0.12);
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 6px;
  padding: 8px 14px;
  color: white;
  font-size: 0.875rem;
  font-family: var(--font);
  outline: none;
  transition: border-color 0.2s, background 0.2s;
}

.header-search input::placeholder { color: rgba(255,255,255,0.55); }

.header-search input:focus {
  border-color: var(--gold);
  background: rgba(255,255,255,0.18);
}

.header-nav {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}

.header-nav a {
  color: rgba(255,255,255,0.85);
  font-size: 0.9rem;
  font-weight: 500;
  padding: 6px 12px;
  border-radius: 6px;
  transition: color 0.2s, background 0.2s;
}

.header-nav a:hover { color: white; background: rgba(255,255,255,0.1); }

.header-nav .nav-donate {
  background: var(--gold);
  color: var(--navy);
  font-weight: 700;
  border-radius: 6px;
  padding: 7px 16px;
}
.header-nav .nav-donate:hover { background: #f5a020; color: var(--navy); }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  padding: 6px;
  cursor: pointer;
  margin-left: auto;
}

.hamburger span {
  display: block;
  width: 22px;
  height: 2px;
  background: white;
  border-radius: 2px;
  transition: transform 0.2s;
}

.mobile-nav {
  display: none;
  background: #12124a;
  padding: 12px 24px 20px;
}

.mobile-nav.open { display: block; }

.mobile-nav a {
  display: block;
  color: rgba(255,255,255,0.85);
  padding: 10px 0;
  font-size: 1rem;
  font-weight: 500;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.mobile-nav a:last-child { border-bottom: none; }

/* ─── Banner ─── */
.site-banner {
  background: #1b1b5e;
  color: white;
  text-align: center;
  padding: 10px 16px;
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.01em;
}

.site-banner a { color: var(--gold); text-decoration: underline; }

/* ─── Container ─── */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ─── Tag Labels ─── */
.tag {
  display: inline-block;
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 3px 10px;
  border-radius: 4px;
  background: var(--tag-default);
  color: var(--tag-default-text);
}
.tag-ai { background: var(--tag-ai); color: var(--tag-ai-text); }
.tag-scraping { background: var(--tag-scraping); color: var(--tag-scraping-text); }
.tag-db { background: var(--tag-db); color: var(--tag-db-text); }
.tag-elastic { background: var(--tag-elastic); color: var(--tag-elastic-text); }
.tag-data { background: var(--tag-data); color: var(--tag-data-text); }
.tag-python { background: #c8f5d0; color: #1a5c2a; }
.tag-node { background: #d0efd0; color: #1a4a1a; }
.tag-sheets { background: #d0f0e0; color: #1a4a30; }

/* ─── Article Cards ─── */
.article-card {
  background: white;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  overflow: hidden;
  transition: transform 0.2s, box-shadow 0.2s;
  display: flex;
  flex-direction: column;
}

.article-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-hover);
}

.card-thumbnail {
  width: 100%;
  aspect-ratio: 16/9;
  object-fit: cover;
  background: linear-gradient(135deg, #1b1b5e 0%, #0a0a23 100%);
}

.card-thumb-placeholder {
  width: 100%;
  aspect-ratio: 16/9;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 600;
  color: rgba(255,255,255,0.5);
  letter-spacing: 0.08em;
}

.card-body {
  padding: 16px;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.card-title {
  font-size: 0.975rem;
  font-weight: 700;
  line-height: 1.45;
  color: var(--text);
  flex: 1;
}

.card-title a:hover { color: var(--link-blue); }

.card-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.8rem;
  color: var(--text-muted);
}

.author-avatar {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: var(--gold);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.7rem;
  color: var(--navy);
  flex-shrink: 0;
}

.card-meta span { font-weight: 500; }

/* ─── Article Grid ─── */
.section-heading {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--text);
  margin-bottom: 24px;
  padding-bottom: 12px;
  border-bottom: 3px solid var(--gold);
  display: inline-block;
}

.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

/* ─── Featured Article ─── */
.featured-section {
  padding: 40px 0 0;
}

.featured-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--navy);
  min-height: 320px;
  display: flex;
  align-items: flex-end;
  margin-bottom: 48px;
}

.featured-thumb-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #1b1b5e 0%, #0a0a23 60%, #002EAD 100%);
  display: flex;
  align-items: center;
  justify-content: center;
}

.featured-thumb-pattern {
  position: absolute;
  inset: 0;
  background-image: radial-gradient(circle at 20% 50%, rgba(254,172,50,0.12) 0%, transparent 50%),
    radial-gradient(circle at 80% 20%, rgba(0,46,173,0.2) 0%, transparent 40%);
}

.featured-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.85) 0%, rgba(0,0,0,0.2) 60%, transparent 100%);
}

.featured-content {
  position: relative;
  z-index: 2;
  padding: 32px;
  width: 100%;
}

.featured-content .tag {
  margin-bottom: 12px;
}

.featured-title {
  font-size: 1.6rem;
  font-weight: 800;
  color: white;
  line-height: 1.3;
  max-width: 600px;
  margin-bottom: 16px;
}

.featured-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  color: rgba(255,255,255,0.75);
  font-size: 0.875rem;
}

.featured-meta .author-avatar {
  width: 32px;
  height: 32px;
}

/* ─── Load More ─── */
.load-more-wrap {
  text-align: center;
  margin: 40px 0 60px;
}

.btn-load-more {
  background: white;
  border: 2px solid var(--navy);
  color: var(--navy);
  font-weight: 700;
  padding: 12px 32px;
  border-radius: 6px;
  font-size: 0.95rem;
  transition: all 0.2s;
}

.btn-load-more:hover {
  background: var(--navy);
  color: white;
}

/* ─── Footer ─── */
.site-footer {
  background: var(--navy);
  color: rgba(255,255,255,0.75);
  padding: 48px 24px 32px;
}

.footer-inner {
  max-width: 1200px;
  margin: 0 auto;
}

.footer-mission {
  font-size: 0.875rem;
  line-height: 1.7;
  max-width: 720px;
  margin-bottom: 32px;
  color: rgba(255,255,255,0.65);
}

.footer-section-title {
  font-size: 0.75rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gold);
  margin-bottom: 12px;
}

.footer-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 32px;
}

.footer-tags a {
  color: rgba(255,255,255,0.7);
  font-size: 0.85rem;
  padding: 4px 0;
  transition: color 0.2s;
}

.footer-tags a:hover { color: var(--gold); }
.footer-tags span { color: rgba(255,255,255,0.25); }

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 16px;
  font-size: 0.82rem;
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  margin-top: 8px;
}

.footer-links a { color: rgba(255,255,255,0.6); }
.footer-links a:hover { color: white; }

/* ─── Page sections spacing ─── */
.page-section {
  padding: 48px 0;
}

/* ─── Responsive ─── */
@media (max-width: 1024px) {
  .article-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .header-search { display: none; }
  .header-nav { display: none; }
  .hamburger { display: flex; }
  .article-grid { grid-template-columns: 1fr; }
  .featured-title { font-size: 1.25rem; }
  .featured-card { min-height: 260px; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .site-header { padding: 0 16px; }
}

/* ─── Learn Page ─── */
.learn-hero {
  background: linear-gradient(135deg, var(--navy) 0%, #1b1b5e 100%);
  color: white;
  padding: 48px 24px;
  text-align: center;
}

.learn-hero h1 {
  font-size: 2rem;
  font-weight: 800;
  margin-bottom: 12px;
}

.learn-hero p {
  font-size: 1.05rem;
  color: rgba(255,255,255,0.8);
  max-width: 600px;
  margin: 0 auto 24px;
}

.btn-primary {
  display: inline-block;
  background: var(--gold);
  color: var(--navy);
  font-weight: 700;
  padding: 12px 28px;
  border-radius: 6px;
  font-size: 0.95rem;
  border: none;
  transition: background 0.2s;
}

.btn-primary:hover { background: #f5a020; color: var(--navy); }

.curriculum-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 20px;
  margin-top: 32px;
}

.curriculum-card {
  background: white;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 20px;
  display: flex;
  align-items: flex-start;
  gap: 16px;
  transition: transform 0.2s, box-shadow 0.2s;
  cursor: pointer;
}

.curriculum-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.curriculum-icon {
  width: 48px;
  height: 48px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  flex-shrink: 0;
}

.curriculum-card h3 {
  font-size: 0.95rem;
  font-weight: 700;
  line-height: 1.4;
  color: var(--text);
  margin-bottom: 4px;
}

.curriculum-card p {
  font-size: 0.82rem;
  color: var(--text-muted);
}

.daily-challenge {
  background: linear-gradient(135deg, #1b1b5e 0%, var(--navy) 100%);
  border-radius: var(--radius-lg);
  padding: 32px;
  color: white;
  text-align: center;
  margin: 32px 0;
}

.daily-challenge h3 {
  font-size: 1.2rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.daily-challenge p {
  color: rgba(255,255,255,0.75);
  margin-bottom: 20px;
}

.challenge-links { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }

.btn-outline-white {
  border: 2px solid rgba(255,255,255,0.6);
  color: white;
  padding: 10px 20px;
  border-radius: 6px;
  font-weight: 600;
  font-size: 0.9rem;
  background: none;
  transition: all 0.2s;
}
.btn-outline-white:hover { border-color: var(--gold); color: var(--gold); }

.section-group {
  margin-bottom: 40px;
}

.section-group-title {
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--navy);
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.section-group-title::after {
  content: '';
  flex: 1;
  height: 2px;
  background: var(--border);
}

.resource-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.resource-list li {
  background: var(--bg-light);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 12px 16px;
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text);
  transition: background 0.2s;
  cursor: pointer;
}

.resource-list li:hover { background: white; box-shadow: var(--shadow); }

.resource-list li .badge {
  background: #e0e7ff;
  color: #3730a3;
  font-size: 0.7rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* ─── Donate Page ─── */
.donate-hero {
  background: linear-gradient(135deg, var(--navy) 0%, #1b1b5e 100%);
  color: white;
  padding: 64px 24px;
  text-align: center;
}

.donate-hero h1 {
  font-size: 2.5rem;
  font-weight: 800;
  margin-bottom: 20px;
}

.donate-hero p {
  font-size: 1.05rem;
  color: rgba(255,255,255,0.8);
  max-width: 680px;
  margin: 0 auto;
  line-height: 1.8;
}

.donation-form-card {
  background: white;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  padding: 32px;
  max-width: 520px;
  margin: -32px auto 48px;
  position: relative;
  z-index: 10;
  border: 1px solid var(--border);
}

.donation-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
}

.donation-tab {
  flex: 1;
  padding: 12px 8px;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: white;
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text-muted);
  transition: all 0.2s;
}

.donation-tab.active {
  border-color: var(--gold);
  background: var(--gold);
  color: var(--navy);
}

.donation-tab:hover:not(.active) {
  border-color: var(--navy);
  color: var(--navy);
}

.donation-desc {
  font-size: 0.9rem;
  color: var(--text-muted);
  text-align: center;
  margin-bottom: 20px;
  line-height: 1.6;
  background: #f8f8fd;
  padding: 12px 16px;
  border-radius: 8px;
  border: 1px solid var(--border);
}

.donation-desc strong { color: var(--text); }

.btn-donate {
  width: 100%;
  background: var(--gold);
  color: var(--navy);
  font-weight: 800;
  font-size: 1.1rem;
  padding: 14px;
  border: none;
  border-radius: 8px;
  transition: background 0.2s;
  letter-spacing: 0.02em;
}

.btn-donate:hover { background: #f5a020; }

.donation-sublabel {
  text-align: center;
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-top: 10px;
}

.donation-sublabel a { color: var(--link-blue); text-decoration: underline; }

/* ─── Supporter Benefits ─── */
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  margin-top: 24px;
}

.benefit-item {
  background: var(--bg-light);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.benefit-icon {
  width: 36px;
  height: 36px;
  background: var(--gold);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  flex-shrink: 0;
}

.benefit-item h4 { font-size: 0.9rem; font-weight: 700; margin-bottom: 4px; }
.benefit-item p { font-size: 0.8rem; color: var(--text-muted); line-height: 1.5; }

/* ─── Stats ─── */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 20px;
  margin-top: 24px;
}

.stat-card {
  background: white;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  text-align: center;
}

.stat-number {
  font-size: 2rem;
  font-weight: 900;
  color: var(--navy);
  line-height: 1;
  margin-bottom: 8px;
}

.stat-label {
  font-size: 0.82rem;
  color: var(--text-muted);
  line-height: 1.5;
}

/* ─── Initiatives ─── */
.initiatives-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 20px;
}

.initiatives-list li {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 16px;
  background: white;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font-size: 0.9rem;
  line-height: 1.5;
}

.init-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gold);
  flex-shrink: 0;
  margin-top: 6px;
}

/* ─── FAQ Accordion ─── */
.faq-list {
  margin-top: 24px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.faq-item {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  background: white;
}

.faq-question {
  width: 100%;
  text-align: left;
  padding: 16px 20px;
  background: none;
  border: none;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  transition: background 0.2s;
  cursor: pointer;
  font-family: var(--font);
}

.faq-question:hover { background: var(--bg-light); }

.faq-chevron {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform 0.3s;
  color: var(--text-muted);
}

.faq-item.open .faq-chevron { transform: rotate(180deg); }

.faq-answer {
  display: none;
  padding: 0 20px 16px;
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.7;
  border-top: 1px solid var(--border);
  padding-top: 14px;
}

.faq-item.open .faq-answer { display: block; }

/* ─── Tag Pages ─── */
.tag-hero {
  background: var(--bg-light);
  padding: 32px 0;
  border-bottom: 1px solid var(--border);
}

.tag-hero-title {
  font-size: 2rem;
  font-weight: 900;
  color: var(--navy);
  margin-bottom: 4px;
}

