  background: white;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  text-align: center;
}

.stat-number {
  font-size: 2rem;
  font-weight: 900;
  color: var(--navy);
  line-height: 1;
  margin-bottom: 8px;
}

.stat-label {
  font-size: 0.82rem;
  color: var(--text-muted);
  line-height: 1.5;
}

/* ─── Initiatives ─── */
.initiatives-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 20px;
}

.initiatives-list li {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 16px;
  background: white;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font-size: 0.9rem;
  line-height: 1.5;
}

.init-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gold);
  flex-shrink: 0;
  margin-top: 6px;
}

/* ─── FAQ Accordion ─── */
.faq-list {
  margin-top: 24px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.faq-item {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  background: white;
}

.faq-question {
  width: 100%;
  text-align: left;
  padding: 16px 20px;
  background: none;
  border: none;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  transition: background 0.2s;
  cursor: pointer;
  font-family: var(--font);
}

.faq-question:hover { background: var(--bg-light); }

.faq-chevron {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform 0.3s;
  color: var(--text-muted);
}

.faq-item.open .faq-chevron { transform: rotate(180deg); }

.faq-answer {
  display: none;
  padding: 0 20px 16px;
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.7;
  border-top: 1px solid var(--border);
  padding-top: 14px;
}

.faq-item.open .faq-answer { display: block; }

/* ─── Tag Pages ─── */
.tag-hero {
  background: var(--bg-light);
  padding: 32px 0;
  border-bottom: 1px solid var(--border);
}

.tag-hero-title {
  font-size: 2rem;
  font-weight: 900;
  color: var(--navy);
  margin-bottom: 4px;
}

.tag-hero-count {
  font-size: 1rem;
  color: var(--text-muted);
}

.popular-tags-strip {
  padding: 20px 0;
  border-bottom: 1px solid var(--border);
  background: white;
}

.popular-tags-label {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 12px;
}

.popular-tags-scroll {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 4px;
  scrollbar-width: thin;
  scrollbar-color: var(--border) transparent;
}

.popular-tag-pill {
  display: flex;
  align-items: center;
  gap: 6px;
  background: var(--bg-light);
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 5px 12px;
  font-size: 0.8rem;
  white-space: nowrap;
  transition: all 0.2s;
  cursor: pointer;
  color: var(--text);
  text-decoration: none;
}

.popular-tag-pill:hover {
  background: var(--navy);
  color: white;
  border-color: var(--navy);
}

.popular-tag-pill .count {
  font-size: 0.7rem;
  font-weight: 700;
  background: rgba(0,0,0,0.1);
  border-radius: 10px;
  padding: 1px 6px;
}

.popular-tag-pill:hover .count { background: rgba(255,255,255,0.2); }

/* ─── Two-column donate layout ─── */
@media (max-width: 768px) {
  .benefits-grid { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .donate-hero h1 { font-size: 1.75rem; }
  .learn-hero h1 { font-size: 1.5rem; }
  .tag-hero-title { font-size: 1.5rem; }
  .curriculum-grid { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .stats-grid { grid-template-columns: 1fr; }
  .donation-tabs { flex-wrap: wrap; }
  .donation-tab { flex: 1 1 calc(50% - 4px); }
}

/* ─── Section bg alternation ─── */
.bg-light { background: var(--bg-light); }
.bg-white { background: white; }

/* ─── Utility ─── */
.text-center { text-align: center; }
.mt-8 { margin-top: 8px; }
.mt-16 { margin-top: 16px; }
.mt-24 { margin-top: 24px; }
.mb-8 { margin-bottom: 8px; }
.mb-16 { margin-bottom: 16px; }
.mb-24 { margin-bottom: 24px; }
